namespace A33.Instrument.Protocol;
public sealed class ModbusTcpTransport(string host="192.168.1.100",int port=502) : IModbusTransport { private readonly System.Net.Sockets.TcpClient client=new(); private NetworkStream? stream; public bool IsOpen=>client.Connected; public async Task OpenAsync(CancellationToken ct){await client.ConnectAsync(host,port,ct);stream=client.GetStream();} public async Task<ReadOnlyMemory<byte>> ExchangeAsync(ReadOnlyMemory<byte> request,CancellationToken ct){if(stream is null)throw new InvalidOperationException("transport closed");await stream.WriteAsync(request,ct);var header=new byte[6];await ReadExactly(stream,header,ct);var len=(header[4]<<8)|header[5];if(len<2||len>254)throw new FormatException("invalid MBAP length");var rest=new byte[len];await ReadExactly(stream,rest,ct);return header.Concat(rest).ToArray();} public async Task CloseAsync(){if(stream is not null)await stream.DisposeAsync();client.Close();} public ValueTask DisposeAsync(){client.Dispose();return ValueTask.CompletedTask;} private static async Task ReadExactly(Stream s,byte[] b,CancellationToken ct){var n=0;while(n<b.Length){var r=await s.ReadAsync(b.AsMemory(n),ct);if(r==0)throw new EndOfStreamException();n+=r;}} }
